PARTS_=[('overview','What Ekādaśī Is','The Eleventh Day and the Goddess Who Slew Mura'),('keeping-the-vow','Keeping the Vow','Fasting, the Night, and Breaking the Fast')]+[(s,f'The Ekādaśīs of {m}',' and '.join(EK[k]['name'] for k in ks)) for s,m,ks,_ in MONTHS]
